 "content": "from collections import Counter

# The frequent non-background color identifies the shape class.
SHAPES = {
    1: ((0, 0, 1), (1, 1, 0), (0, 1, 0)),
    2: ((0, 0, 0), (1, 1, 1), (0, 0, 0)),
    3: ((0, 1, 1), (0, 1, 0), (0, 1, 0)),
}

def transform(grid):
    counts = Counter(v for row in grid for v in row if v != 0)
    color = max(counts, key=counts.get)
    shape = SHAPES[color]
    return [[8 * cell for cell in row] for row in shape]
